import{_ as e}from"./chunks/home.pc.en.BIVUBvtu.js";import{_ as o}from"./chunks/home-estop.pc.en.BSpMx1St.js";import{_ as n,o as a,c as s,a5 as r}from"./chunks/framework.D47SInms.js";const w=JSON.parse('{"title":"Control home","description":"","frontmatter":{"layout":"doc","outline":"deep"},"headers":[],"relativePath":"manual/gui/control-home.md","filePath":"manual/gui/control-home.md","lastUpdated":1791600043000}'),i={name:"manual/gui/control-home.md"};function h(d,t,l,c,g,p){return a(),s("div",null,[...t[0]||(t[0]=[r('<h1 id="control-home" tabindex="-1">Control home <a class="header-anchor" href="#control-home" aria-label="Permalink to &quot;Control home&quot;">​</a></h1><p>The control home is the screen you drive the robot from. Open it with <strong>Control</strong> on the Hub. The whole screen is the viewport — a camera feed or the 3D view — with a motion card on the left, an <strong>OBSERVE</strong> card on the right, and two virtual joysticks in the lower corners when no gamepad is connected.</p><p><img src="'+e+'" alt="Control home"></p><div class="danger custom-block"><p class="custom-block-title">DANGER</p><p>Every motion button on this screen moves the real robot. <strong>Keep people, animals, and obstacles at least 2 m clear of the robot whenever it is operating.</strong> Check your surroundings before you press anything, and keep a hand near <code>E-STOP</code>.</p></div><h2 id="top-bar" tabindex="-1">Top bar <a class="header-anchor" href="#top-bar" aria-label="Permalink to &quot;Top bar&quot;">​</a></h2><p>The top bar floats over the video in two groups. From left to right:</p><table tabindex="0"><thead><tr><th>Element</th><th>What it shows / does</th></tr></thead><tbody><tr><td>Logo</td><td>Goes to the <strong>Hub</strong>. The robot stops where it is and stays connected</td></tr><tr><td>Status light</td><td>A green, amber, or red light that pulses slowly — fast when something is critical, and a steady red while not connected. Tap it for <strong>Overall system status</strong> (see <a href="/RBQ/nightly/manual/gui/connection.html#connection-status-in-the-top-bar">Connection</a>)</td></tr><tr><td>Gait chip</td><td>The robot&#39;s current gait name, such as <code>STANDING</code>, colored by state. Hidden while not connected</td></tr><tr><td><code>SLAM</code> chip</td><td>Appears only while external control (SLAM or SDK) is active. Tap it to hand control back to the app</td></tr><tr><td>Signal bars</td><td>WiFi signal strength, and how fast data is moving over the robot link</td></tr><tr><td>Log badge</td><td>Unread log alerts</td></tr><tr><td><strong>Robot</strong> battery, device battery</td><td>The robot pack&#39;s charge, with a charging mark while it charges, and your own device&#39;s battery</td></tr><tr><td><code>E-STOP</code></td><td>Emergency stop — see below</td></tr><tr><td>Quit</td><td>Desktop build only. Asks <strong>Quit the app?</strong> first, then closes the app. The robot keeps running</td></tr></tbody></table><p>If the robot drops off and does not come back within 8 seconds, the app takes you to the Hub on its own, because that is where you reconnect. It also goes back to the Hub the moment the connected robot changes, so you never end up driving a robot you did not pick.</p><h3 id="e-stop" tabindex="-1">E-STOP <a class="header-anchor" href="#e-stop" aria-label="Permalink to &quot;E-STOP&quot;">​</a></h3><p><code>E-STOP</code> never fires on a single tap. Pressing it opens the confirmation <strong>Emergency stop?</strong>, which warns that <em>The robot immediately stops all motion and cuts power. Reinitialization is required to resume control.</em> Press <strong>Stop</strong> to go ahead or <strong>Cancel</strong> to back out. The button behaves the same way on every screen, even with a menu open.</p><p><img src="'+o+'" alt="E-STOP confirmation"></p><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>After an emergency stop the robot has no motor power. Bring it back with <strong>Auto Start</strong> (below) before it can move again. The step chips show you where the sequence stopped.</p></div><h3 id="ownership" tabindex="-1">Ownership <a class="header-anchor" href="#ownership" aria-label="Permalink to &quot;Ownership&quot;">​</a></h3><p>Only one device controls the robot at a time. When another device holds control, the status light turns amber and the <strong>Ownership</strong> row in <strong>Overall system status</strong> reads <code>Take ▸</code> — tap it to take control back. While a SLAM or SDK program is driving, you get the <code>SLAM</code> chip instead.</p><p>While another device holds control, this device spectates: the screen stays visible, the controls below the top bar are locked, and <code>Spectating</code> at the top offers to take control. See <a href="/RBQ/nightly/manual/gui/emergency.html#spectating">Spectating</a>.</p><h2 id="auto-start" tabindex="-1">Auto Start <a class="header-anchor" href="#auto-start" aria-label="Permalink to &quot;Auto Start&quot;">​</a></h2><p>Until the robot&#39;s motor control is running, a green <strong>Auto Start</strong> pill sits at the bottom center of the viewport, grayed out while not connected. Tap it to open the <strong>Auto Start</strong> dialog. The dialog always stays centered on the screen: when the screen is short, only the <strong>Startup sequence</strong> list inside it scrolls and the buttons stay visible. On a short screen such as a phone in landscape, each step shows as one line — tap it to open or close its details. The running step and any failed or warning step open by themselves.</p><ol><li>Read the instruction — <em>Place the robot on a flat floor, and make sure all feet and knees contact the ground.</em></li><li>Five step chips lay out the sequence: <strong>POWER</strong>, <strong>CAN-BUS</strong>, <strong>HOMING</strong>, <strong>IMU-CHECK</strong>, <strong>START</strong>. Tap an unfinished <strong>CAN-BUS</strong> or <strong>HOMING</strong> chip to run just that step.</li><li>Press <strong>Auto Start</strong>. The dialog stays open and the <strong>Startup sequence</strong> panel below the chips fills in step by step — Pre-check, Leg Power, Joint comms, Motor parameters, Home position, IMU, Control active — marking each one <strong>Passed / Failed / Warning / Running</strong>.</li><li>If a step fails, the panel names the cause and the fix. For example: <em>The robot is already standing — Sit the robot down, then start again.</em> Take care of it and press <strong>Start again</strong>.</li><li>Press <strong>Close</strong> once the sequence reports <strong>Done</strong>. When a run you watched here clears the last step, <strong>Start again</strong> disappears and only <strong>Close</strong> remains, so you cannot start the sequence twice by accident.</li></ol><p>You can also start the same sequence from the status light: <strong>Overall system status › ▶ Auto start (full sequence)</strong>.</p><h2 id="viewport-and-source-selector" tabindex="-1">Viewport and source selector <a class="header-anchor" href="#viewport-and-source-selector" aria-label="Permalink to &quot;Viewport and source selector&quot;">​</a></h2><p>The dropdown at the top center of the viewport picks what you see. <code>3D</code>, a live model of the robot, is always there. Camera sources show up only when the robot reports having that camera: <strong>Front</strong>, <strong>Rear</strong>, <strong>Left</strong>, <strong>Right</strong>, <strong>Stairs</strong>, <strong>Quad</strong>, <strong>Panorama</strong>, <code>CCTV</code>, <strong>Thermal</strong>, <strong>PTZ Mix</strong>, and <code>SLAM</code> on LiDAR robots. Tap outside the list to close it without changing the source.</p><p>Pick a PTZ-type source and the pan/tilt/zoom panel appears over the video. Drag it by its handle to move it.</p><p>While docking runs, the selector reads <code>Dock</code> and will not open — the viewport belongs to <a href="/RBQ/nightly/manual/gui/camera-vision.html#dock-view">Dock View</a> until you close it.</p><h2 id="left-card-—-motion" tabindex="-1">Left card — Motion <a class="header-anchor" href="#left-card-—-motion" aria-label="Permalink to &quot;Left card — Motion&quot;">​</a></h2><p>Everything that makes the robot move lives on the left.</p><ul><li><strong>Card</strong>: folded, it is a round glass button with a walking-person icon. Tap it and the circle grows into the card; tap the card&#39;s top row to fold it back. The app remembers whether each card is open, and both start open.</li><li><strong>Body</strong>: the fixed motion buttons <code>SIT</code>, <code>STAND</code>, <code>WALK</code>, <code>STAIRS</code>, and <code>DOCKING</code> (only while docking is available), plus <strong>Motion</strong>, the dashed button that opens the full motion grid. Whichever button matches the robot&#39;s current gait is highlighted. See <a href="/RBQ/nightly/manual/gui/motion-commands.html">Motion commands</a>.</li><li><strong>Tool buttons</strong>: a row of small buttons outside the card, just right of the left joystick — at the left edge in gamepad mode. Each one opens its panel above the row: <ul><li><strong>Drive</strong> — speed, body height, and tilt sliders (<a href="/RBQ/nightly/manual/gui/motion-commands.html#drive-parameters">Drive parameters</a>).</li><li><strong>Arm</strong> — only on robots with a manipulator.</li><li><strong>Input</strong> — the input mode <strong>Auto / Virtual / Pad</strong> and the live gamepad map. <em>Auto</em> switches to a physical gamepad whenever one is connected. A green dot means external control is doing the driving.</li></ul></li><li>When the card is taller than the screen, a <code>▾</code> at the bottom tells you it scrolls.</li></ul><h2 id="right-card-—-observe" tabindex="-1">Right card — OBSERVE <a class="header-anchor" href="#right-card-—-observe" aria-label="Permalink to &quot;Right card — OBSERVE&quot;">​</a></h2><p>Everything about <em>what you see and hear</em> lives on the right.</p><ul><li><strong>Card</strong>: folded, it is a round glass button, and it opens and folds like the left card.</li><li><strong>Body</strong>: <ul><li><strong>Vision</strong> — the vision toggles, including <strong>P2G</strong> (Point-to-Go), which is available only while <strong>Front</strong> is the source. With P2G on, tapping a spot on the floor in the video sends the robot walking there.</li><li><strong>Scene</strong> — 3D view settings, shown only while <code>3D</code> is the source.</li><li><strong>Audio</strong> — listen to the robot, volume, and devices. A green dot means listening is on.</li><li><code>SLAM</code> — LiDAR robots only.</li><li><strong>PTZ</strong> — robots with a PTZ camera only. Switches the view to the PTZ camera; tap again to go back to the source you were on.</li></ul></li><li><strong>Talk</strong>: the button at the bottom right, just left of the right joystick, or at the right edge in gamepad mode. Hold it to talk through the robot&#39;s speaker. It reads <strong>Talking</strong> for as long as you hold it, and it is grayed out while the speaker amplifier is off.</li><li><strong>Sounds · Capture</strong>: the two buttons just left of <code>Talk</code>. <code>Sounds</code> picks a sound and plays it on a loop on the robot. <code>Capture</code> asks whether you want a <code>Photo</code> or a <code>Record</code>ing; while recording, the button shows the elapsed time in red and tapping it again stops. When the screen is too narrow to fit them beside the center gauges, the two buttons stack above <code>Talk</code>. See <a href="/RBQ/nightly/manual/gui/media.html#control-home">Media</a>.</li><li><strong>Gyro</strong> and <strong>Speed HUD</strong> sit side by side at the bottom center of the video. Tap the gyro to enlarge it. You can turn both off in <strong>App settings</strong>.</li><li>In the <strong>simulator</strong> there are no side cards and the 3D view fills the screen. The robot is always walking, and the tool row at the bottom holds <code>Drive</code>, <code>Level</code> and <code>Reset</code>. Pick the view from the drop-down at the top center; progress is shown below it. See the simulator notes in <a href="./connection.html">Connection</a> for levels and views.</li></ul><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>With <strong>P2G</strong> on, the whole video area is a command surface — every tap on the floor moves the robot. Turn it off when you are done.</p></div><h2 id="joysticks-and-input-modes" tabindex="-1">Joysticks and input modes <a class="header-anchor" href="#joysticks-and-input-modes" aria-label="Permalink to &quot;Joysticks and input modes&quot;">​</a></h2><ul><li><strong>Without a gamepad</strong>, on touch devices and PCs, the screen shows two virtual joysticks. What the axes do depends on the current motion — see the axis tables in <a href="/RBQ/nightly/manual/gui/motion-commands.html">Motion commands</a>.</li><li><strong>With a gamepad</strong>, whether a physical pad or a Steam Deck, the virtual joysticks disappear and you drive with the pad&#39;s sticks. Fold the cards to see more of the video.</li><li><strong>One-stick mode</strong> in Settings › Gamepad swaps the left and right stick roles so you can drive one-handed.</li></ul><p><strong>Driving from the keyboard</strong> — on a PC with no gamepad, the keyboard works alongside the virtual joysticks. It works only on this screen: the same keys do nothing on the Hub or in settings.</p><table tabindex="0"><thead><tr><th>Key</th><th>What it does</th></tr></thead><tbody><tr><td><kbd>W</kbd> <kbd>A</kbd> <kbd>S</kbd> <kbd>D</kbd></td><td>Left stick — forward/back and sideways</td></tr><tr><td><kbd>Q</kbd> <kbd>E</kbd></td><td>Right stick left / right — turn left / right</td></tr><tr><td><kbd>↑</kbd> <kbd>↓</kbd> <kbd>←</kbd> <kbd>→</kbd></td><td>Right stick</td></tr></tbody></table><p>The robot moves while you hold a key and stops when you let go. The keyboard has no emergency-stop key — <strong>E-STOP is the button at the top right of the screen</strong>.</p><p>While connected, the bottom-left corner shows the current gait name as a small HUD.</p><h2 id="compact-layout" tabindex="-1">Compact layout <a class="header-anchor" href="#compact-layout" aria-label="Permalink to &quot;Compact layout&quot;">​</a></h2><p>On short screens — phones, or a window less than 500 px tall — the layout stays the same and only the pieces get smaller. The joysticks, tool buttons, and walkie-talkie tuck into the corners, and the left card takes only the space above them and scrolls. On narrow screens the cards get narrower too. Nothing is taken away.</p><p>On very small screens — less than 720 px wide, such as a small phone in landscape — the screen shows less. The tool buttons at the bottom and the buttons beside <code>Talk</code> show icons only, <code>E-STOP</code> at the top right shows only its emergency icon, and the signal bars in the transfer-rate chip and the gyro at the center shrink or go away. Everything still works the same.</p><blockquote><p><strong>What developer mode adds here</strong> is collected on <a href="/RBQ/nightly/manual/gui/developer-mode.html#control-home">Developer mode</a>.</p></blockquote>',40)])])}const y=n(i,[["render",h]]);export{w as __pageData,y as default};
